import pytest

from senna.physics.fits.params_writer import (
    HEADER,
    IncompleteParamsError,
    render_params,
    validate_complete,
)

GENERATED_AT = "2026-07-17T00:00:00Z"
# F03 reuses the F02 emitter byte for byte; only the file's self-description changes
TRANSFORMS_HEADER = (
    "# SENNA — 2026 transforms (F03). Generated by senna.physics.synth.run;\n"
    "# edit the transforms or configs/synth.yaml, never this file by hand.\n"
)


def _transforms():
    # leaves are (value, origin) pairs, one of each provenance kind plus a
    # donor-flagged fallback — the shapes transforms.yaml actually carries
    return {
        "monza": {
            "t0_2026_s": (82.1, "fitted: fit_point_mass.ipynb"),
            "energy": {
                "h_max_mj": (8.5, "sourced: circuits.yaml AR-05 baseline, 2026-07-17"),
                "e_dep_mj": (7.9, "fitted: fit_energy_budget.ipynb"),
            },
        },
        "paul_ricard": {
            "corner_exponent": (0.25, "stylised — T2 prior fallback via donor cluster"),
        },
    }


def test_null_guard():
    validate_complete(_transforms())  # complete transforms pass silently

    broken = _transforms()
    broken["monza"]["energy"]["e_dep_mj"] = (None, "fitted: fit_energy_budget.ipynb")
    broken["paul_ricard"]["corner_exponent"] = (None, "stylised — T2 prior fallback")

    with pytest.raises(IncompleteParamsError) as excinfo:
        validate_complete(broken)

    # make synth debugging starts from this message — it must name the dotted paths
    assert "monza.energy.e_dep_mj" in str(excinfo.value)
    assert "paul_ricard.corner_exponent" in str(excinfo.value)


def test_byte_deterministic():
    # two consecutive make synth runs must leave `git diff` empty
    assert render_params(_transforms(), GENERATED_AT) == render_params(
        _transforms(), GENERATED_AT
    )


def test_every_leaf_carries_provenance():
    rendered = render_params(_transforms(), GENERATED_AT, header=TRANSFORMS_HEADER)

    def is_value_line(line: str) -> bool:
        before_comment = line.split("#", 1)[0].strip()
        if not before_comment or ":" not in before_comment:
            return False
        return before_comment.split(":", 1)[1].strip() != ""

    value_lines = [line for line in rendered.splitlines() if is_value_line(line)]
    assert value_lines  # the check must actually bite

    # the interpretability contract survives the new header: no number without an origin
    for line in value_lines:
        assert "  # " in line, f"uncommented value line: {line!r}"
        assert any(origin in line for origin in ("sourced", "fitted", "stylised")), (
            f"no origin on: {line!r}"
        )


def test_custom_header_replaces_default():
    rendered = render_params(_transforms(), GENERATED_AT, header=TRANSFORMS_HEADER)

    assert rendered.startswith(TRANSFORMS_HEADER)
    assert HEADER not in rendered  # transforms.yaml must not claim to be physics_params

    # and the default keeps F02 output byte-identical, so make fit does not churn
    assert render_params(_transforms(), GENERATED_AT).startswith(HEADER)
